package com.quizrank.backend.controller;
import com.quizrank.backend.entity.*; import com.quizrank.backend.repository.*; import com.quizrank.backend.service.UploadStorageService;
import org.springframework.core.io.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile; import org.springframework.web.server.ResponseStatusException;
import java.nio.file.*; import java.time.*; import java.util.*;
@RestController @RequestMapping("/api/learning") public class LearningResourceController {
 private final AssignmentRepository assignments; private final LearningMaterialRepository materials; private final AssignmentSubmissionRepository submissions; private final UserRepository users; private final UploadStorageService storage;
 public LearningResourceController(AssignmentRepository a,LearningMaterialRepository m,AssignmentSubmissionRepository s,UserRepository u,UploadStorageService st){assignments=a;materials=m;submissions=s;users=u;storage=st;}
 private User requireRole(Integer id,User.Role role){User u=users.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"User not found")); if(u.getRole()!=role) throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Not allowed"); return u;}
 private ResponseEntity<Resource> download(String stored,String name){try{Path p=storage.path(stored); Resource r=new UrlResource(p.toUri()); if(!r.exists()) throw new ResponseStatusException(HttpStatus.NOT_FOUND,"File not found"); return ResponseEntity.ok().contentType(MediaType.APPLICATION_PDF).header(HttpHeaders.CONTENT_DISPOSITION,ContentDisposition.attachment().filename(name).build().toString()).body(r);}catch(Exception e){if(e instanceof ResponseStatusException x)throw x;throw new ResponseStatusException(HttpStatus.NOT_FOUND,"File not found");}}
 @GetMapping("/assignments") public List<Assignment> allAssignments(){return assignments.findAllByOrderByCreatedAtDesc();}
 @GetMapping("/assignments/teacher/{id}") public List<Assignment> teacherAssignments(@PathVariable Integer id){requireRole(id,User.Role.TEACHER);return assignments.findByTeacherIdOrderByCreatedAtDesc(id);}
 @GetMapping("/assignments/student/{id}") public List<Assignment> studentAssignments(@PathVariable Integer id){requireRole(id,User.Role.STUDENT);return assignments.findAllByOrderByCreatedAtDesc();}
 @PostMapping(value="/assignments",consumes=MediaType.MULTIPART_FORM_DATA_VALUE) public Assignment createAssignment(@RequestParam Integer teacherId,@RequestParam(required=false) Integer subjectId,@RequestParam String title,@RequestParam(required=false) String description,@RequestParam(required=false) String dueDate,@RequestPart("file") MultipartFile file) throws Exception {requireRole(teacherId,User.Role.TEACHER);if(title.isBlank()||title.length()>180)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Title is required (max 180 characters)"); Assignment a=new Assignment();a.setTeacherId(teacherId);a.setSubjectId(subjectId);a.setTitle(title.trim());a.setDescription(description);a.setDueDate(dueDate==null||dueDate.isBlank()?null:LocalDate.parse(dueDate));a.setFileName(file.getOriginalFilename());a.setStoredName(storage.savePdf(file));return assignments.save(a);}
 @GetMapping("/assignments/{id}/download") public ResponseEntity<Resource> assignmentFile(@PathVariable Integer id){Assignment a=assignments.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));return download(a.getStoredName(),a.getFileName());}
 @PostMapping(value="/assignments/{id}/submissions",consumes=MediaType.MULTIPART_FORM_DATA_VALUE) public AssignmentSubmission submit(@PathVariable Integer id,@RequestParam Integer studentId,@RequestPart("file") MultipartFile file)throws Exception {requireRole(studentId,User.Role.STUDENT);assignments.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Assignment not found"));String stored=storage.savePdf(file);AssignmentSubmission s=submissions.findByAssignmentIdAndStudentId(id,studentId).orElseGet(AssignmentSubmission::new);s.setAssignmentId(id);s.setStudentId(studentId);s.setFileName(file.getOriginalFilename());s.setStoredName(stored);return submissions.save(s);}
 @GetMapping("/assignments/{id}/submissions/teacher/{teacherId}") public List<AssignmentSubmission> assignmentSubmissions(@PathVariable Integer id,@PathVariable Integer teacherId){requireRole(teacherId,User.Role.TEACHER);Assignment a=assignments.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));if(!a.getTeacherId().equals(teacherId))throw new ResponseStatusException(HttpStatus.FORBIDDEN);return submissions.findByAssignmentId(id);}
 @GetMapping("/submissions/{id}/download") public ResponseEntity<Resource> submissionFile(@PathVariable Integer id){AssignmentSubmission s=submissions.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));return download(s.getStoredName(),s.getFileName());}
 @GetMapping("/materials") public List<LearningMaterial> allMaterials(){return materials.findAllByOrderByCreatedAtDesc();}
 @GetMapping("/materials/teacher/{id}") public List<LearningMaterial> teacherMaterials(@PathVariable Integer id){requireRole(id,User.Role.TEACHER);return materials.findByTeacherIdOrderByCreatedAtDesc(id);}
 @PostMapping(value="/materials",consumes=MediaType.MULTIPART_FORM_DATA_VALUE) public LearningMaterial createMaterial(@RequestParam Integer teacherId,@RequestParam(required=false) Integer subjectId,@RequestParam String title,@RequestParam(required=false) String description,@RequestPart("file") MultipartFile file)throws Exception {requireRole(teacherId,User.Role.TEACHER);if(title.isBlank()||title.length()>180)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Title is required");LearningMaterial m=new LearningMaterial();m.setTeacherId(teacherId);m.setSubjectId(subjectId);m.setTitle(title.trim());m.setDescription(description);m.setFileName(file.getOriginalFilename());m.setStoredName(storage.savePdf(file));return materials.save(m);}
 @GetMapping("/materials/{id}/download") public ResponseEntity<Resource> materialFile(@PathVariable Integer id){LearningMaterial m=materials.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));return download(m.getStoredName(),m.getFileName());}
}
